const Icon=({icon:I,...p})=><I size={18} strokeWidth={1.7} aria-hidden="true" {...p}/>;
const Tag=({children,tone=''})=><span className={'tag '+tone}>{children}</span>;
const Field=({label,children,hint})=><label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;
const Empty=({title,desc,children})=><div className="empty"><span className="emptyicon"><Icon icon={CalendarDays}/></span><h3>{title}</h3><p>{desc}</p>{children}</div>;
function Modal({title,children,onClose,wide=false}){const ref=useRef(null);useEffect(()=>{const last=document.activeElement;document.body.style.overflow='hidden';const node=ref.current;const focusables=()=>[...node.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled);focusables()[0]?.focus();const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const fs=focusables(),a=fs[0],z=fs.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();z?.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a?.focus()}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow='';document.removeEventListener('keydown',key);last?.focus()}},[]);return <div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className={'modal '+(wide?'wide':'')+(title==='Panduan Demo'?' guide-modal':'')} ref={ref} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><h2 id="dialog-title">{title}</h2><button className="iconbtn" onClick={onClose} aria-label="Close dialog"><Icon icon={X}/></button></header>{children}</section></div>}
function ScheduleFields({value,onChange}){const change=(key,v)=>onChange({...value,[key]:v});return <><div className="grid three"><Field label="Date"><input type="date" required value={value.date} onChange={e=>change('date',e.target.value)}/></Field><Field label="Start Time"><input type="time" required value={value.start} onChange={e=>change('start',e.target.value)}/></Field><Field label="End Time"><input type="time" required value={value.end} onChange={e=>change('end',e.target.value)}/></Field></div><div className="grid two"><Field label="Room"><select value={value.room} onChange={e=>change('room',e.target.value)}>{ROOMS.map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Main Teacher / Moderator"><select value={value.teacher} onChange={e=>change('teacher',e.target.value)}>{TEACHERS.map(v=><option key={v}>{v}</option>)}</select></Field></div><p className="muted timezone"><Icon icon={Clock}/> Times use Asia/Jakarta.</p></>}
const blankSchedule=()=>({date:'2026-11-20',start:'15:00',end:'16:30',room:ROOMS[0],teacher:TEACHERS[0]});
function CreateEvent({onSave,onCancel}){const [draft,setDraft]=useState({name:'',type:'Trial',book:'All Courses — Trial',language:'ID',free:true,price:150000,active:true});const [row,setRow]=useState(blankSchedule());const [rows,setRows]=useState([]);const [error,setError]=useState('');const set=(key,v)=>setDraft({...draft,[key]:v});const limit=isSingle(draft.type),invalid=limit&&rows.length>1;function add(){if(limit&&rows.length>=1)return;if(!row.date||!row.start||!row.end||row.end<=row.start){setError('Enter a date and an end time after the start time.');return}setRows([...rows,{...row,id:'DRAFT-'+Date.now()}]);setError('')}function submit(e){e.preventDefault();if(!draft.name.trim()){setError('Enter an event name.');return}if(!rows.length||invalid){setError(limit?'Add exactly one schedule.':'Add at least one schedule.');return}onSave({...draft,name:draft.name.trim(),price:draft.type==='Internal Meeting'?null:draft.free?0:Number(draft.price),schedules:rows})}
return <><div className="pagehead"><div><button className="back" onClick={onCancel}><Icon icon={ArrowLeft}/> Events</button><h1>Create Event</h1><p>Choose an event type. Its schedule rules apply automatically.</p></div><div className="actions"><button onClick={onCancel}>Discard</button><button className="primary" form="create-form" disabled={invalid}>Save Event</button></div></div><form id="create-form" onSubmit={submit}><div className="creategrid"><div><section className="card"><h2><Icon icon={BookOpen}/> Basic Information</h2><Field label="Branch Availability"><select><option>HQ Training</option></select></Field><Field label="Event Type"><select aria-label="Event Type" value={draft.type} onChange={e=>set('type',e.target.value)}>{TYPES.map(t=><option key={t}>{t}</option>)}</select></Field><Field label="Event Name" hint={HINTS[draft.type]}><input aria-label="Event Name" required placeholder={HINTS[draft.type]} value={draft.name} onChange={e=>set('name',e.target.value)}/></Field><div className="grid two"><Field label="Book"><select value={draft.book} onChange={e=>set('book',e.target.value)}>{['All Courses — Trial','Digital Literacy Workshop','Roblox Coder','Mentoring Handbook'].map(b=><option key={b}>{b}</option>)}</select></Field><Field label="Language Book"><select value={draft.language} onChange={e=>set('language',e.target.value)}><option>ID</option><option>EN</option></select></Field></div>{draft.type==='Internal Meeting'?<div className="notice"><Icon icon={ShieldCheck}/><div><b>Not available for student orders</b><p>Internal Meeting pricing is not defined in the brief. No checkout is created in this demo.</p></div></div>:<><label className="switchrow"><input type="checkbox" checked={draft.free} onChange={e=>set('free',e.target.checked)}/> Free event</label><div className="grid two"><Field label="Currency"><select disabled={draft.free}><option>IDR</option></select></Field><Field label="Base Price"><input type="number" min="1" disabled={draft.free} required={!draft.free} value={draft.free?'':draft.price} placeholder="Base Price" onChange={e=>set('price',e.target.value)}/></Field></div></>}</section><section className="card"><h2><Icon icon={CalendarDays}/> Schedule <Tag>{limit?'1 schedule only':'Multiple schedules allowed'}</Tag></h2>{invalid&&<p className="error" role="alert">{draft.type} allows one schedule. Remove the extra rows before saving.</p>}<fieldset className="schedule-builder" aria-label="Add schedule fields" disabled={limit&&rows.length>=1}><ScheduleFields value={row} onChange={setRow}/><div className="alignright"><button type="button" onClick={add} disabled={limit&&rows.length>=1}><Icon icon={Plus}/> Add Schedule</button></div></fieldset>{limit&&rows.length===1&&<p className="muted">One schedule added. Remove it first if you need another date.</p>}{rows.length>0&&<div className="tablewrap"><table><thead><tr><th>Date</th><th>Time</th><th>Room</th><th>Action</th></tr></thead><tbody>{rows.map((s,i)=><tr key={s.id}><td>{dateLabel(s.date)}</td><td>{s.start}–{s.end}</td><td>{s.room}</td><td><button type="button" className="text danger" aria-label={'Remove schedule '+(i+1)} onClick={()=>setRows(rows.filter(x=>x.id!==s.id))}>Remove</button></td></tr>)}</tbody></table></div>}{!rows.length&&<div className="inset">No schedule added yet. Add {limit?'one schedule':'at least one schedule'} to continue.</div>}{error&&<p className="error" role="alert">{error}</p>}</section></div><aside className="card settingscard"><h2><Icon icon={Settings}/> Settings</h2><label className="switchrow"><input type="checkbox" checked={draft.active} onChange={e=>set('active',e.target.checked)}/> Active</label><hr/><h3>Type rules</h3><p>{limit?'One date, one session.':'One or more dated sessions.'}</p><p>{draft.type==='Internal Meeting'?'Student ordering is blocked.':'Free and paid events are supported.'}</p><small>Changing the type never deletes schedule rows or renames your draft.</small></aside></div></form></>}
export default function Demo(){const [db,setDB]=useState(()=>upgradeRegistrationWorkflow(enrichSeed(seed())));const [movementDraft,setMovementDraft]=useState(null);const [selections,setSelections]=useState({});const [flowModal,setFlowModal]=useState(null);const [ready,setReady]=useState(false);const [route,setRoute]=useState('/events');const [modal,setModal]=useState(null);const [toast,setToast]=useState('');const [query,setQuery]=useState('');const [filter,setFilter]=useState('All types');const [navOpen,setNavOpen]=useState(false);const [scheduleDraft,setScheduleDraft]=useState(blankSchedule());const [modalError,setModalError]=useState('');const [assigned,setAssigned]=useState([]);const [searchStudent,setSearchStudent]=useState('');const [presenceDraft,setPresenceDraft]=useState({presence:'Present',late:0,note:'',journal:''});const [regDone,setRegDone]=useState(false);const [regError,setRegError]=useState('');const [importRows,setImportRows]=useState([]);const [importName,setImportName]=useState('');const [importBusy,setImportBusy]=useState(false);const [importMatrix,setImportMatrix]=useState([]);
useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved&&Array.isArray(saved.events))setDB(upgradeRegistrationWorkflow(saved))}catch{}setReady(true);const read=()=>{setRoute(window.location.hash.slice(1)||'/events');setModal(null);setFlowModal(null);setRegDone(false);setNavOpen(false)};read();window.addEventListener('hashchange',read);return()=>window.removeEventListener('hashchange',read)},[]);
useEffect(()=>{if(ready)try{localStorage.setItem(STORE,JSON.stringify(db))}catch{}},[db,ready]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)}},[toast]);
const go=url=>{setRoute(url);setFlowModal(null);setToast('');window.location.hash=url;setModal(null);setNavOpen(false)};const open=(kind,extra={})=>{setToast('');setModalError('');setSearchStudent('');setImportRows([]);setImportMatrix([]);setImportName('');setModal({kind,...extra})};const close=()=>setModal(null);const notify=msg=>setToast(msg);const parts=route.split('/').filter(Boolean);const event=db.events.find(e=>e.id===parts[1]);const tab=parts[2]||'details';const at=db.events.flatMap(e=>e.schedules.map(s=>({event:e,schedule:s}))).find(x=>x.schedule.id===parts[1]);const updateEvent=(id,fn,action)=>setDB(prev=>({...prev,events:prev.events.map(e=>e.id===id?fn(e):e),audit:[...prev.audit,{action,event:id,at:new Date().toISOString()}]}));
function scheduleOpen(e,s){setScheduleDraft(s?{...s}:blankSchedule());open('schedule',{eventId:e.id,scheduleId:s?.id})}
function scheduleSave(ev){ev.preventDefault();if(modal.scheduleId){setModalError('Use the reviewed Reschedule flow to change an existing schedule.');return;}const e=db.events.find(e=>e.id===modal.eventId);if(!scheduleDraft.date||scheduleDraft.end<=scheduleDraft.start){setModalError('End time must be after start time.');return}const active=e.schedules.filter(s=>s.status!=='Dropped'&&s.status!=='Finished');if(!modal.scheduleId&&isSingle(e.type)&&active.length){setModalError('An active schedule already exists. Drop it first.');return}updateEvent(e.id,old=>({...old,schedules:modal.scheduleId?old.schedules.map(s=>s.id===modal.scheduleId?{...s,...scheduleDraft}:s):[...old.schedules,{...scheduleDraft,id:'OCC-'+Date.now(),status:'Upcoming',assigned:[],attendance:{}}]}),modal.scheduleId?'Edit schedule':'Add schedule');close();notify('Schedule saved. Existing participants and sessions are unchanged.')}
function dropSave(){updateEvent(modal.eventId,e=>({...e,schedules:e.schedules.map(s=>s.id===modal.scheduleId?{...s,status:'Dropped'}:s)}),'Drop schedule');close();notify('Schedule dropped. Participants, sessions and payments stay unchanged.')}
function attendanceOpen(e,s,student){setPresenceDraft(s.attendance[student.id]||{presence:'Not Recorded',late:0,note:'',journal:''});open('presence',{eventId:e.id,scheduleId:s.id,studentId:student.id})}
function savePresence(ev){ev.preventDefault();updateEvent(modal.eventId,e=>({...e,schedules:e.schedules.map(s=>s.id===modal.scheduleId?{...s,attendance:{...s.attendance,[modal.studentId]:presenceDraft}}:s)}),'Update demo attendance');close();notify('Attendance saved for this occurrence only.')}
function createSave(d){const id='EV-'+Date.now();const e={id,type:d.type,name:d.name,book:d.book,language:d.language,price:d.price,active:d.active,members:[],formEnabled:false,schedules:d.schedules.map((s,i)=>({...s,id:id+'-S'+(i+1),status:'Upcoming',assigned:[],attendance:{}}))};setDB(prev=>({...prev,events:[e,...prev.events]}));go('/events/'+id+'/details');notify('Event created. Add participants before assigning them to a schedule.')}
function memberSave(){const e=db.events.find(e=>e.id===modal.eventId);updateEvent(e.id,old=>({...old,members:[...old.members,...students.filter(s=>assigned.includes(s.id)&&!old.members.some(m=>m.id===s.id)).map(s=>simulatedMember(s,old))]}),'Add demo registrations');close();notify('Demo students added with simulated applied amounts at the event price. No real payment, purchase or invoice was created.')}
function assignSave(){updateEvent(modal.eventId,e=>({...e,schedules:e.schedules.map(s=>s.id===modal.scheduleId?{...s,assigned:assigned.filter(id=>e.members.some(m=>m.id===id))}:s)}),'Assign existing registrations');close();notify('Students assigned using their existing sessions.')}
async function loadImport(file){if(!file)return;setModalError('');setImportBusy(true);setImportRows([]);setImportMatrix([]);setImportName(file.name);try{if(file.size>2*1024*1024)throw new Error('Demo limit: 2 MB per file.');let matrix;if(/\.csv$/i.test(file.name))matrix=parseCSV(await file.text());else if(/\.xlsx$/i.test(file.name)){const {readSheet}=await import('read-excel-file/browser');matrix=await readSheet(file)}else throw new Error('Choose a .xlsx or UTF-8 .csv file.');const e=db.events.find(e=>e.id===modal.eventId);if(e?.type!=='Workshop')throw new Error('Participant import is available for Workshop only.');setImportMatrix(matrix);setImportRows(validateImport(matrix,e.members))}catch(e){setModalError(e.message||'Could not read this file.')}finally{setImportBusy(false)}}
function commitImport(){const e=db.events.find(e=>e.id===modal.eventId);if(e?.type!=='Workshop')return;try{const checked=validateImport(importMatrix,e.members);if(checked.some(r=>r.errors.length))throw new Error('Resolve every invalid or duplicate row, then upload again.');const stamp=Date.now();updateEvent(e.id,old=>({...old,members:[...old.members,...checked.map((r,i)=>({id:'IMP-'+stamp+'-'+i,name:r.name,phone:r.phone,age:r.age,parent:'—',session:null,origin:'Spreadsheet',registrationStatus:'Registered (demo)'}))]}),'Import demo participants');close();notify(checked.length+' participants imported. No purchase session or invoice created.')}catch(err){setModalError(err.message)}}
const publicEvent=parts[0]==='register'?event:null;
function registrationSubmit(ev){
  ev.preventDefault();
  if(!publicEvent){setRegError('This registration form is not available.');return;}
  const data=new FormData(ev.currentTarget);
  try {
    const next=submitWorkshopRegistration(db,publicEvent.id,{name:data.get('name'),phone:data.get('phone'),age:data.get('age')});
    setDB(next);setRegDone(true);setRegError('');
  } catch(error){setRegError(error.message);}
}
if(!ready)return <div className="loading">Loading demo…</div>;
if(parts[0]==='register')return <div className="publicpage"><div className="publicbrand"><GraduationCap size={30}/><span>timedoor <b>academy</b></span></div>{publicEvent?.type==='Workshop'&&publicEvent.formEnabled?<section className="publiccard"><Tag>Workshop</Tag><h1>{publicEvent.name}</h1><p className="muted">HQ Training · {publicEvent.schedules.filter(s=>s.status!=='Dropped').map(s=>dateLabel(s.date)).join(' & ')}</p>{regDone?<div className="empty"><CheckCircle2 size={42} color="#18853c"/><h2>Data pendaftaran telah dikirim</h2><p>Pendaftaran masuk daftar calon peserta (Pending) untuk ditinjau admin. Belum menjadi peserta terkonfirmasi dan bukan konfirmasi pembayaran atau kursi.</p><button onClick={()=>setRegDone(false)}>Isi formulir lagi</button></div>:<form onSubmit={registrationSubmit}><Field label="Nama *"><input name="name" required autoComplete="name" placeholder="Nama peserta"/></Field><Field label="No HP *"><input name="phone" type="tel" required autoComplete="tel" placeholder="Nomor yang dapat dihubungi"/></Field><Field label="Usia *"><input name="age" type="number" min="0" required placeholder="Usia dalam tahun"/></Field>{regError&&<p className="error" role="alert">{regError}</p>}<button className="primary full">Daftar</button><small className="publicnote">Prototype: data hanya tersimpan di browser ini. Gunakan data contoh, bukan data pribadi.</small></form>}</section>:<section className="publiccard"><h1>Form not available</h1><p>Generate a Workshop registration form from the demo first.</p></section>}<button className="text" onClick={()=>go('/events')}>Back to CMS demo</button></div>;
return <div className="app"><aside className={'sidebar '+(navOpen?'open':'')}><a className="brand" href="#/events"><img src="/brand/timedoor-logo.png" alt="Timedoor Academy"/><Icon icon={PanelLeftClose}/></a><div className="branch"><span>HQ Training</span><Icon icon={ChevronDown}/></div><button className="navitem" onClick={()=>notify('Dashboard is outside this event prototype.')}><Icon icon={Home}/> Dashboard</button><span className="navlabel">MENU</span>{[['Analytic',BarChart3],['Accounting',Wallet]].map(([n,I])=><button className="navitem" key={n} onClick={()=>notify(n+' is outside this event prototype.')}><Icon icon={I}/>{n}<Icon icon={ChevronRight}/></button>)}<div className="navparent"><Icon icon={Package}/> Product <Icon icon={ChevronDown}/></div><div className="subnav">{['Package','Event','Trial','Learning Path','Add Ons','Item'].map(n=><button key={n} className={'navitem '+(n==='Event'&&(['move','transfers'].includes(parts[0])||(parts[0]==='events'&&filter!=='Trial'))?'active':n==='Trial'&&parts[0]==='events'&&filter==='Trial'?'active':'')} onClick={()=>{if(n==='Event'||n==='Trial'){setFilter(n==='Trial'?'Trial':'All types');go('/events')}else notify(n+' is outside this event prototype.')}}><span className="navdot"/>{n}</button>)}</div><button className="navitem" onClick={()=>notify('Customer is outside this event prototype.')}><Icon icon={UserRound}/> Customer <Icon icon={ChevronRight}/></button><div className="navparent"><Icon icon={GraduationCap}/> Class <Icon icon={ChevronDown}/></div><div className="subnav"><button className="navitem" onClick={()=>notify('Class List is outside this event prototype.')}><span className="navdot"/> List Class</button><button className={'navitem '+(parts[0]==='attendance'?'active':'')} onClick={()=>go('/attendance')}><span className="navdot"/> Class Attendance</button></div><button className="navitem" onClick={()=>notify('Teacher directory is outside this event prototype.')}><Icon icon={Users}/> Teacher <Icon icon={ChevronRight}/></button><button className="navitem" onClick={()=>notify('Approval is outside this event prototype.')}><Icon icon={ListChecks}/> Approval</button><span className="navlabel">CURRICULUM</span>{['Question Bank','Test','Book'].map(n=><button className="navitem" key={n} onClick={()=>notify(n+' is outside this event prototype.')}><Icon icon={BookOpen}/>{n}</button>)}<span className="navlabel">MASTER DATA</span>{['Room','Branch','Subject','Course','User','User Role','Holiday','Survey'].map(n=><button className="navitem" key={n} onClick={()=>notify(n+' is outside this event prototype.')}><Icon icon={Layers}/>{n}</button>)}<div className="sidebarbottom"><Tag>Static prototype</Tag><p>No API · No real payments</p></div></aside><div className="workspace"><header className="topbar"><div><button className="iconbtn mobilemenu" aria-label="Open navigation" onClick={()=>setNavOpen(!navOpen)}><Icon icon={Menu}/></button></div><div className="topactions"><button className="text" onClick={()=>open('guide')}>Demo Guide</button><button className="text" onClick={()=>open('order')}>Student Order Check</button><button className="iconbtn" onClick={()=>open('reset')} aria-label="Reset demo data"><Icon icon={RefreshCw}/></button><span className="zone">Asia/Jakarta <Icon icon={ChevronDown}/></span><Icon icon={Sun}/><span className="avatar">DA</span></div></header><main><details className="demo-clock"><summary>Demo clock: {formatMoment(nowOf(db))} · Asia/Jakarta <span>Simulation — not today</span></summary><label>Demo date and time <input aria-label="Demo date and time" type="datetime-local" value={new Date(nowOf(db)+7*3600000).toISOString().slice(0,16)} onChange={ev=>{if(ev.target.value)setDB({...db,demoNow:new Date(ev.target.value+':00+07:00').toISOString()})}}/></label><small>Use 28 Sep 2026, 10:00 to test the supplied reschedule example. At exactly 11:00 its cutoff blocks changes.</small></details>
{parts[0]==='events'&&!event&&parts[1]!=='create'&&<><div className="pagehead"><div><div className="eyebrow">PRODUCT / EVENT</div><h1>Events</h1><p>Manage event types, participants and dated sessions.</p></div><button className="primary" onClick={()=>go('/events/create')}><Icon icon={Plus}/> Create Event</button></div><div className="listmeta"><span><b>{db.events.length}</b> events in this branch</span><Tag>Interactive demo</Tag></div><section className="card listcard"><div className="toolbar"><div className="search"><Icon icon={Search}/><input aria-label="Search events" placeholder="Search event name…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="Filter event type" value={filter} onChange={e=>setFilter(e.target.value)}><option>All types</option>{TYPES.map(t=><option key={t}>{t}</option>)}</select></div><div className="tablewrap"><table><thead><tr><th>Event Name</th><th>Type</th><th>Students</th><th>Schedules</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody>{db.events.filter(e=>(filter==='All types'||e.type===filter)&&e.name.toLowerCase().includes(query.toLowerCase())).map(e=><tr key={e.id}><td><a className="eventlink" href={'#/events/'+e.id+'/details'}>{e.name}</a><small>{e.id}</small></td><td>{e.type==='Parent Teacher Meeting (PTM)'?'PTM':e.type}</td><td>{e.type==='Internal Meeting'?'—':e.members.length}</td><td>{e.schedules.filter(s=>s.status!=='Dropped').length} sessions</td><td>{money(e.price)}</td><td><Tag tone={e.active?'green':''}>{e.active?'Active':'Inactive'}</Tag></td><td><button className="text" onClick={()=>go('/events/'+e.id+'/details')}>View <Icon icon={ChevronRight}/></button></td></tr>)}</tbody></table></div>{!db.events.some(e=>(filter==='All types'||e.type===filter)&&e.name.toLowerCase().includes(query.toLowerCase()))&&<Empty title="No matching events" desc="Try another name or reset the type filter."><button onClick={()=>{setQuery('');setFilter('All types')}}>Clear filters</button></Empty>}<div className="tablefooter">Showing events in HQ Training. Changes are stored locally for this demo.</div></section><div className="guidebar"><Icon icon={ShieldCheck}/><div><b>Coba Reschedule</b><p>Ubah jadwal yang sama melalui Schedule → Reschedule → Review. Hanya siswa yang di-assign mengikuti; peserta event, Session, dan pembayaran tetap.</p></div><button className="text" onClick={()=>{const trial=db.events.find(e=>e.type==='Trial'&&e.active&&e.schedules.some(s=>!rescheduleEligibility(db,e,s)))||db.events.find(e=>e.type==='Trial');if(trial)go('/events/'+trial.id+'/schedule');else open('guide')}}>Buka Schedule <Icon icon={ChevronRight}/></button></div></>}
{parts[0]==='events'&&parts[1]==='create'&&<CreateEvent onSave={createSave} onCancel={()=>go('/events')}/>}
{parts[0]==='events'&&event&&<><div className="pagehead"><div><button className="back" onClick={()=>go('/events')}><Icon icon={ArrowLeft}/> Events</button><h1>Detail Event</h1><p>{event.name} <span className="dot">·</span> {event.id} <span className="dot">·</span> {event.type} <span className="dot">·</span> HQ Training</p></div><Tag tone="green">{event.active?'Active':'Inactive'}</Tag></div><nav className="tabs" aria-label="Event detail tabs">{['details','participants','attendance','schedule'].map(t=><a key={t} href={'#/events/'+event.id+'/'+t} className={tab===t?'selected':''}>{t[0].toUpperCase()+t.slice(1)}</a>)}</nav>
{tab==='details'&&<div className="creategrid"><div><section className="card"><h2><Icon icon={BookOpen}/> Basic Information</h2><dl>{[['Product ID',event.id],['Branch Availability','HQ Training'],['Event Type',event.type],['Book — Language',event.book?event.book+' — '+event.language:'Not specified'],['Base Price',money(event.price)]].map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl></section><section className="card"><div className="sectionhead"><h2><Icon icon={CalendarDays}/> Schedule</h2><button className="text" onClick={()=>go('/events/'+event.id+'/schedule')}>Manage in Schedule <Icon icon={ChevronRight}/></button></div><p className="muted">Read-only summary. Schedule changes are managed in the Schedule tab.</p><ScheduleTable db={db} event={event} readonly go={go}/></section></div><aside className="card settingscard"><h2><Icon icon={Settings}/> Settings</h2><Tag tone="green">{event.active?'Active':'Inactive'}</Tag><hr/><h3>Order availability</h3><p>{event.type==='Internal Meeting'?'Not available for student orders.':'Free or paid, according to the event price.'}</p><h3>Participants</h3><p>{seatCount(event)} registered · Session IDs preserved</p></aside></div>}
{tab==='participants'&&<Participants db={db} event={event} onAdd={()=>{setAssigned([]);open('members',{eventId:event.id})}} onImport={()=>open('import',{eventId:event.id})} onGenerate={()=>open('generate',{eventId:event.id})} selection={selections[event.id]||[]} onSelection={ids=>setSelections({...selections,[event.id]:ids})} onMove={ids=>{setMovementDraft({sourceId:event.id,ids,absent:{},reason:'',note:'',notify:true,destination:''});go('/move/'+event.id)}} onViewTransfer={id=>go('/transfers/'+id)} onConfirmRegistrations={ids=>{try{setDB(confirmWorkshopRegistrations(db,event.id,ids));notify(ids.length+' submissions confirmed to Student List. No payment or schedule assignment created.');return ''}catch(error){return error.message}}} onDemoPayment={m=>open('demoAmount',{eventId:event.id,studentId:m.id})} onRemove={m=>open('remove',{eventId:event.id,studentId:m.id})}/>}
{(tab==='schedule'||tab==='attendance')&&<><div className="sectionhead scheduleshead"><div><h2>{tab==='schedule'?'Event Schedule':'Attendance by Schedule'}</h2><p className="muted">{tab==='schedule'?'Manage occurrences without changing event memberships.':'See complete attendance details before or after the event finishes.'}</p></div>{tab==='schedule'&&<div className="actions"><button disabled={event.type==='Internal Meeting'||!event.schedules.some(s=>s.status==='Upcoming'||s.status==='Ongoing')} onClick={()=>{const s=event.schedules.find(s=>s.status==='Upcoming'||s.status==='Ongoing');setAssigned(s.assigned);open('assign',{eventId:event.id,scheduleId:s.id})}}><Icon icon={Users}/> Assign Students</button><button className="primary" disabled={isSingle(event.type)&&event.schedules.some(s=>s.status==='Upcoming'||s.status==='Ongoing')} onClick={()=>scheduleOpen(event)}><Icon icon={Plus}/> Add Schedule</button></div>}</div>{tab==='schedule'&&isSingle(event.type)&&event.schedules.some(s=>s.status==='Upcoming'||s.status==='Ongoing')&&<div className="notice"><Icon icon={AlertCircle}/><span>{event.type==='Trial'?'Trial':'PTM'} allows one active schedule. Drop the current upcoming schedule before adding another.{event.type!=='Trial'&&' (PTM replacement policy is a demo proposal.)'}</span></div>}<section className="card"><ScheduleTable db={db} event={event} go={(url)=>{if(url.startsWith('/attendance/'))sessionStorage.setItem('attendance-back','/events/'+event.id+'/'+tab);go(url)}} onAdd={()=>scheduleOpen(event)} onReschedule={s=>setFlowModal({kind:'reschedule',eventId:event.id,scheduleId:s.id})} onHistory={s=>setFlowModal({kind:'history',eventId:event.id,scheduleId:s.id})} onAssign={s=>{setAssigned(s.assigned);open('assign',{eventId:event.id,scheduleId:s.id})}} onDrop={s=>open('drop',{eventId:event.id,scheduleId:s.id})} attendanceOnly={tab==='attendance'}/></section><div className="invariant"><Icon icon={ShieldCheck}/><span>{event.members.length} event members · {event.members.filter(m=>m.session).length} original session references · No new invoice on schedule changes</span></div></>}
</>}
{parts[0]==='attendance'&&!at&&<><div className="pagehead"><div><div className="eyebrow">CLASS / ATTENDANCE</div><h1>Class Attendance</h1><p>Event occurrences use the same attendance detail, even before Finish.</p></div></div><div className="attendancecards">{db.events.flatMap(e=>e.schedules.filter(s=>s.status!=='Dropped').map(s=><section className="card attendancecard" key={s.id}><div className="sectionhead"><div><Tag>{e.type==='Parent Teacher Meeting (PTM)'?'PTM':e.type}</Tag><h2>{e.name}</h2></div><button onClick={()=>{sessionStorage.setItem('attendance-back','/attendance');go('/attendance/'+s.id)}}>See Details <Icon icon={ChevronRight}/></button></div><div className="attendancecardmeta"><span><Icon icon={CalendarDays}/>{dateLabel(s.date)} · {s.start}–{s.end}</span><span><Icon icon={MapPin}/>{s.room}</span><span><Icon icon={Users}/>{s.assigned.length} students</span><Tag tone={s.status==='Ongoing'?'amber':'green'}>{s.status}</Tag></div></section>))}</div></>}
{parts[0]==='attendance'&&at&&<><div className="pagehead"><div><button className="back" onClick={()=>go(sessionStorage.getItem('attendance-back')||'/attendance')}><Icon icon={ArrowLeft}/> Back to schedules</button><h1>Attendance Detail</h1><p>{at.event.name} · {dateLabel(at.schedule.date)} · {at.schedule.start}–{at.schedule.end}</p></div><Tag tone={at.schedule.status==='Ongoing'?'amber':'green'}>{at.schedule.status}</Tag></div><div className="demolifecycle"><span>Demo lifecycle</span><select aria-label="Demo lifecycle" value={at.schedule.status} disabled={at.schedule.status==='Dropped'} onChange={ev=>{updateEvent(at.event.id,e=>({...e,schedules:e.schedules.map(s=>s.id===at.schedule.id?{...s,status:ev.target.value}:s)}),'Change demo lifecycle')}}>{['Upcoming','Ongoing','Finished','Dropped'].map(s=><option disabled={s==='Dropped'} key={s}>{s}</option>)}</select><small>Manual demo state, not calculated from today.</small></div><div className="metrics"><Metric title="Room Name" value={at.schedule.room} icon={MapPin}/><Metric title="Total Students" value={at.schedule.assigned.length} icon={Users}/><Metric title="Total Teachers" value="1" icon={GraduationCap}/></div><section className="card"><h2>Teacher List</h2><div className="tablewrap"><table><thead><tr><th>Teacher Name</th><th>Role</th></tr></thead><tbody><tr><td><div className="teacher"><span className="avatar soft">NK</span><b>{at.schedule.teacher}</b></div></td><td><Tag tone="blue">Main Teacher</Tag></td></tr></tbody></table></div></section><section className="card"><div className="sectionhead"><h2>Student List <Tag>{at.schedule.assigned.length} students</Tag></h2></div>{at.event.type==='Internal Meeting'?<Empty title="Staff attendance pending specification" desc="Student ordering remains blocked. The staff attendee/journal model is not defined in the brief."/>:!at.schedule.assigned.length?<Empty title="No students assigned to this occurrence" desc="Use Assign Students in the event Schedule tab. Existing event registrations stay intact."/>:<div className="tablewrap"><table className="attendance-table"><thead><tr><th>Student Name</th><th>Session</th><th>Addons</th><th>Presence</th><th>Meeting Journal</th><th>Late</th><th>Note</th><th>Action</th></tr></thead><tbody>{at.event.members.filter(m=>at.schedule.assigned.includes(m.id)).map(s=>{const a=at.schedule.attendance[s.id]||{};return <tr key={s.id}><td><b>{s.name}</b><small>{s.id}</small></td><td>{s.session||'Not linked'}</td><td>—</td><td><Tag tone={a.presence==='Present'?'green':a.presence==='Absent'?'red':''}>{a.presence||'Not Recorded'}</Tag></td><td>{a.journal?<button className="text" onClick={()=>open('journal',{student:s,schedule:at.schedule,entry:a})}>See Meeting Journal</button>:<span className="muted">No Meeting Journal Available</span>}</td><td>{a.presence?a.late?'Yes, '+a.late+' min':'No':'—'}</td><td>{a.note||'—'}</td><td><button className="text" disabled={at.schedule.status!=='Ongoing'} onClick={()=>attendanceOpen(at.event,at.schedule,s)}>Change Presence</button></td></tr>})}</tbody></table></div>}<p className="muted footnote">Attendance editing is enabled only in Ongoing demo state. Finished records stay viewable. Journal editor is a minimal demo proposal, not the exact production schema.</p></section></>}
{!['events','attendance','move','transfers'].includes(parts[0])&&<Empty title="Page not found" desc="Return to the event demo."><button onClick={()=>go('/events')}>Events</button></Empty>}
{parts[0]==='move'&&movementDraft&&<TransferWizard db={db} draft={movementDraft} onDraft={setMovementDraft} onCancel={ids=>{if(Array.isArray(ids))setSelections({...selections,[movementDraft.sourceId]:ids});go('/events/'+movementDraft.sourceId+'/participants')}} onCommit={()=>{try{const result=commitMove(db,movementDraft);setDB(result.db);setSelections({...selections,[movementDraft.sourceId]:[]});go('/transfers/batch/'+result.batchId);return ''}catch(error){return error.message}}}/>}
{parts[0]==='move'&&!movementDraft&&<Empty title="Select participants first" desc="Start a transfer from the source event Participants tab."><button onClick={()=>go('/events/'+parts[1]+'/participants')}>Back to Participants</button></Empty>}
{parts[0]==='transfers'&&parts[1]==='batch'&&<BatchResult db={db} batchId={parts[2]} go={go}/>}
{parts[0]==='transfers'&&parts[1]!=='batch'&&<TransferDetail key={parts[1]} db={db} transferId={parts[1]} go={go} onVerify={(id,ref,authorized)=>{try{setDB(verifyDemoPayment(db,id,ref,authorized));notify('Demo payment verification recorded. Destination participant is now Active.');return ''}catch(error){return error.message}}}/>}
</main><footer className="appfooter">Timedoor Academy CMS <span>Prototype · static data · locally persisted</span></footer></div>{toast&&<div className="toast" role="status"><Icon icon={CheckCircle2}/>{toast}<button className="iconbtn" aria-label="Dismiss notification" onClick={()=>setToast('')}><Icon icon={X}/></button></div>}
{flowModal?.kind==='reschedule'&&<RescheduleFlow db={db} eventId={flowModal.eventId} scheduleId={flowModal.scheduleId} onClose={()=>setFlowModal(null)} onCommit={draft=>{try{setDB(commitReschedule(db,flowModal.eventId,flowModal.scheduleId,draft));setFlowModal(null);notify('Schedule rescheduled. Only assigned participants follow; original payments and registrations are unchanged.');return ''}catch(error){return error.message}}}/>}
{flowModal?.kind==='history'&&(()=>{const e=db.events.find(e=>e.id===flowModal.eventId);return <ScheduleHistory event={e} schedule={e.schedules.find(s=>s.id===flowModal.scheduleId)} onClose={()=>setFlowModal(null)}/>})()}
{modal&&<Modal title={{schedule:modal.scheduleId?'Edit Schedule':'Add Schedule',drop:'Drop Schedule?',assign:'Assign Students',members:'Add Demo Students',presence:'Change Presence',journal:'Meeting Journal',import:'Import Participants',generate:'Workshop Registration Form',reset:'Reset demo data?',guide:'Panduan Demo',order:'Student Order Check',remove:'Remove Participant',demoAmount:'Set Simulated Applied Amount'}[modal.kind]} onClose={close} wide={['assign','presence','import'].includes(modal.kind)}>
{modal.kind==='demoAmount'&&(()=>{const e=db.events.find(e=>e.id===modal.eventId),m=e.members.find(m=>m.id===modal.studentId);return <form onSubmit={ev=>{ev.preventDefault();try{const amount=Number(new FormData(ev.currentTarget).get('amount'));setDB(setDemoAppliedAmount(db,e.id,m.id,amount));close();notify('Simulated applied amount saved. Existing assignments retained; no real payment was verified.')}catch(error){setModalError(error.message)}}}><div className="modalbody"><div className="notice"><Icon icon={AlertCircle}/><div><b>Demo / Simulated — not a real payment</b><p>For manually added demo students only. This does not change original payments, imports or form registrations.</p></div></div><h3>{m.name}</h3><Field label="Simulated applied amount (IDR)"><input aria-label="Simulated applied amount" name="amount" type="number" min="0" step="1" required defaultValue={Number.isFinite(m.paidAmount)?m.paidAmount:e.price??0}/></Field><p>Default = source event price. Rp 0 is valid for a free event. Assign this student to one source schedule before moving.</p>{modalError&&<p className="error" role="alert">{modalError}</p>}</div><div className="modalfooter"><button type="button" onClick={close}>Cancel</button><button className="primary">Save Simulated Amount</button></div></form>})()}
{modal.kind==='remove'&&(()=>{const e=db.events.find(e=>e.id===modal.eventId),m=e.members.find(m=>m.id===modal.studentId),blocked=!!m.session||e.schedules.some(s=>s.attendance[m.id]);return <><div className="modalbody"><p>{m.name}</p>{blocked?<p className="error">Financial or attendance records must be retained. Use Move Participants instead of deleting this registration.</p>:<p>Remove this local demo registration and its assignments? No order or payment is deleted.</p>}</div><div className="modalfooter"><button onClick={close}>Cancel</button><button className="destructive" disabled={blocked} onClick={()=>{updateEvent(e.id,old=>({...old,members:old.members.filter(v=>v.id!==m.id),schedules:old.schedules.map(t=>({...t,assigned:t.assigned.filter(id=>id!==m.id)}))}),'Remove demo registration');close()}}>Remove Participant</button></div></>})()}
{modal.kind==='schedule'&&<form onSubmit={scheduleSave}><div className="modalbody"><ScheduleFields value={scheduleDraft} onChange={setScheduleDraft}/><div className="notice"><Icon icon={ShieldCheck}/><span>Event participants, existing sessions and payments stay unchanged.</span></div>{modalError&&<p className="error" role="alert">{modalError}</p>}</div><div className="modalfooter"><button type="button" onClick={close}>Cancel</button><button className="primary">Save Schedule</button></div></form>}
{modal.kind==='drop'&&<><div className="modalbody"><p>Drop this upcoming occurrence? The event itself will stay active.</p><div className="inset">{(()=>{const e=db.events.find(e=>e.id===modal.eventId),s=e.schedules.find(s=>s.id===modal.scheduleId);return <><b>{e.name}</b><p>{dateLabel(s.date)} · {s.start}–{s.end} · {s.room}</p></>})()}</div><div className="notice"><Icon icon={ShieldCheck}/><span>Participants, original sessions and payments remain. Existing attendance/journals are kept on this occurrence.</span></div></div><div className="modalfooter"><button onClick={close}>Cancel</button><button className="destructive" onClick={dropSave}>Drop Schedule</button></div></>}
{['assign','members'].includes(modal.kind)&&<><div className="modalbody"><p>{modal.kind==='assign'?'Choose existing event registrations for this occurrence. No new order or session is created.':'Adds demo students with a simulated applied amount equal to the source event price (Rp 0 for free events). No real purchase or payment is recorded.'}</p><div className="search"><Icon icon={Search}/><input aria-label="Search students" placeholder="Search students…" value={searchStudent} onChange={e=>setSearchStudent(e.target.value)}/></div>{(()=>{const e=db.events.find(e=>e.id===modal.eventId),pool=modal.kind==='assign'?e.members:students.filter(s=>!e.members.some(m=>m.id===s.id));return pool.filter(s=>s.name.toLowerCase().includes(searchStudent.toLowerCase())).map(s=><label className="selectrow" key={s.id}><input type="checkbox" checked={assigned.includes(s.id)} onChange={ev=>setAssigned(ev.target.checked?[...assigned,s.id]:assigned.filter(id=>id!==s.id))}/><div><b>{s.name}</b><small>{s.id}{modal.kind==='assign'?' · '+(s.session||'No purchase session'):''}</small></div></label>)})()}<small>{assigned.length} selected · Event membership is preserved.</small></div><div className="modalfooter"><button onClick={close}>Cancel</button><button className="primary" disabled={modal.kind==='members'&&!assigned.length} onClick={modal.kind==='members'?memberSave:assignSave}>{modal.kind==='members'?'Add':'Assign'} {assigned.length} Students</button></div></>}
{modal.kind==='presence'&&<form onSubmit={savePresence}><div className="modalbody"><div className="presence-context">{(()=>{const e=db.events.find(e=>e.id===modal.eventId),m=e.members.find(m=>m.id===modal.studentId),s=e.schedules.find(s=>s.id===modal.scheduleId);return <><b>{m.name}</b><small>{m.session} · {dateLabel(s.date)} · {s.start}–{s.end}</small></>})()}</div><div className="grid two"><Field label="Presence"><select value={presenceDraft.presence} onChange={e=>setPresenceDraft({...presenceDraft,presence:e.target.value})}>{['Not Recorded','Present','Absent'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Late (minutes)"><input type="number" min="0" value={presenceDraft.late} onChange={e=>setPresenceDraft({...presenceDraft,late:Number(e.target.value)})}/></Field></div><Field label="Note"><input value={presenceDraft.note} onChange={e=>setPresenceDraft({...presenceDraft,note:e.target.value})}/></Field><Field label="Meeting Journal" hint="Minimal demo text field; production journal schema is pending."><textarea aria-label="Meeting Journal" rows="3" value={presenceDraft.journal} onChange={e=>setPresenceDraft({...presenceDraft,journal:e.target.value})}/></Field></div><div className="modalfooter"><button type="button" onClick={close}>Cancel</button><button className="primary">Save Attendance</button></div></form>}
{modal.kind==='journal'&&<><div className="modalbody"><Tag>Read-only demo journal</Tag><h3>{modal.student.name}</h3><p>{modal.student.session} · {dateLabel(modal.schedule.date)}</p><div className="inset journaltext">{modal.entry.journal}</div><small>Minimal viewer. Exact production journal fields are not included.</small></div><div className="modalfooter"><button onClick={close}>Close</button></div></>}
{modal.kind==='import'&&<><div className="modalbody"><div className="notice"><Icon icon={AlertCircle}/><div><b>Provisional demo format: Nama · No HP · Usia</b><p>Based on the registration fields. This spreadsheet format is a proposal, not finalized in the brief.</p></div></div><div className="actions"><a className="downloadbtn" href="/templates/workshop-participants.xlsx" download>Download XLSX Template</a><a className="downloadbtn" href="/templates/workshop-participants.csv" download>Download CSV Template</a></div><label className="uploadplaceholder"><FileDown size={26}/><b>Choose a spreadsheet</b><small>.xlsx or UTF-8 .csv · first sheet · up to 2 MB / 1,000 rows</small><input aria-label="Upload participants spreadsheet" type="file" accept=".xlsx,.csv" disabled={importBusy} onChange={e=>loadImport(e.target.files?.[0])}/></label>{importBusy&&<p role="status">Reading spreadsheet…</p>}{modalError&&<p className="error" role="alert">{modalError}</p>}{importRows.length>0&&<><div className="importsummary"><b>{importName}</b><span>{importRows.length} rows · {importRows.filter(r=>!r.errors.length).length} valid · {importRows.filter(r=>r.errors.length).length} need correction</span></div><div className="tablewrap previewtable"><table><thead><tr><th>Row</th><th>Nama</th><th>No HP</th><th>Usia</th><th>Validation</th></tr></thead><tbody>{importRows.map(r=><tr key={r.row}><td>{r.row}</td><td>{r.name||'—'}</td><td>{r.phone||'—'}</td><td>{Number.isFinite(r.age)?r.age:'—'}</td><td>{r.errors.length?<span className="invalidrow">{r.errors.join('; ')}</span>:<Tag tone="green">Ready</Tag>}</td></tr>)}</tbody></table></div><small>All rows must be valid. Import adds participants to this Workshop only. It does not create orders, paid sessions or invoices.</small></>}</div><div className="modalfooter"><button onClick={close}>Cancel</button><button className="primary" disabled={importBusy||!importRows.length||importRows.some(r=>r.errors.length)} onClick={commitImport}>Import {importRows.length||''} Participants</button></div></>}
{modal.kind==='generate'&&(()=>{const e=db.events.find(e=>e.id===modal.eventId),url=window.location.href.split('#')[0]+'#/register/'+e.id;return <><div className="modalbody"><Tag>Workshop</Tag><h3>{e.name}</h3><p>Registration fields: <b>Nama · No HP · Usia</b></p><p className="muted">Demo link works only where this prototype is hosted. Submissions enter Pending first. Admin selects and confirms them to Student List; no payment or automatic schedule assignment is created.</p>{e.formEnabled&&<><Field label="Demo registration link"><input readOnly value={url}/></Field><div className="actions"><button onClick={async()=>{try{await navigator.clipboard.writeText(url);notify('Demo link copied.')}catch{notify('Copy the link from the field above.')}}}>Copy Link</button><button onClick={()=>go('/register/'+e.id)}>Preview Form <Icon icon={ExternalLink}/></button></div></>}</div><div className="modalfooter"><button onClick={close}>Close</button>{!e.formEnabled&&<button className="primary" onClick={()=>{updateEvent(e.id,e=>({...e,formEnabled:true}),'Generate local registration form');notify('Demo registration form generated.')}}>Generate Form</button>}</div></>})()}
{modal.kind==='reset'&&<><div className="modalbody"><p>Restore the ten seed events and clear local changes, registrations and demo audit records?</p><small>Only this browser's demo data is affected.</small></div><div className="modalfooter"><button onClick={close}>Cancel</button><button className="destructive" onClick={()=>{setDB(upgradeRegistrationWorkflow(enrichSeed(seed())));close();go('/events');setFilter('All types');setQuery('');notify('Demo data reset.')}}>Reset Data</button></div></>}
{modal.kind==='guide'&&<><div className="modalbody"><div className="notice"><Icon icon={AlertCircle}/><div><b>Panduan mencoba prototype — bukan proses wajib</b><p>Demo memakai waktu simulasi dan data lokal browser. Tidak ada pembayaran sungguhan atau notifikasi yang dikirim.</p></div></div><ol className="walkthrough"><li><b>Buat event</b><p>Create Event → pilih tipe → isi informasi dan jadwal. Trial/PTM tepat satu jadwal saat pembuatan; Workshop, Bootcamp, dan Internal Meeting dapat memiliki beberapa jadwal.</p></li><li><b>Tambah siswa demo dan lakukan assignment</b><p>Participants → Add Demo Students → pilih siswa → Add. Lalu Schedule → Assign Students. Nilai Demo / Simulated mengikuti harga event, termasuk Rp 0 untuk event gratis. Siswa demo lama yang belum memiliki nilai dapat memakai Set Demo Applied Amount tanpa reset.</p></li><li><b>Reschedule tanpa memindahkan event</b><p>Schedule → menu ⋯ pada jadwal → Reschedule → isi perubahan dan alasan → Continue → review → centang persetujuan → Confirm Reschedule. Jadwal dan ID yang sama diperbarui; hanya siswa yang sudah di-assign mengikuti. Assignment jadwal lain, peserta event, Session, order, dan pembayaran tidak berubah.</p><p>Harus sebelum dua jam dari mulai jadwal lama dan belum ada attendance tercatat. Konflik ruang, teacher, siswa, kapasitas, dan jadwal diperiksa. View History menampilkan perubahan.</p></li><li><b>Move Participants ke event lain</b><p>Participants → pilih satu atau beberapa siswa → Move → pilih tujuan → isi alasan → review → centang persetujuan → Confirm Move. Transfer boleh lintas Trial, Workshop, dan Bootcamp, termasuk book/bahasa berbeda; cabang dan mata uang harus sama. PTM dan Internal Meeting dikecualikan.</p><p>Harga sama: Active tanpa penyesuaian. Harga tujuan lebih tinggi: Reserved dan invoice selisih. Lebih rendah: Remaining Event Value, bukan uang tunai atau wallet. Peserta Absent perlu alasan dan konfirmasi; jatah satu kali hanya terpakai setelah commit. Present, terlambat, atau sudah menerima manfaat tidak dapat dipindahkan.</p></li><li><b>Cek attendance dan hasil transaksi demo</b><p>Schedule → See Details / View Attendance atau Class Attendance membuka jadwal yang sama. Demo lifecycle Ongoing dipakai untuk mencoba presence/journal. View Transfer membuka hasil yang sesuai; Verify Demo Payment hanyalah simulasi dengan konfirmasi dan referensi.</p></li><li><b>Import dan form Workshop</b><p>Participants → Import Participants untuk XLSX/CSV atau Generate Form untuk pendaftaran contoh. Form masuk Pending di Form Submissions. Pilih satu/beberapa calon → Confirm to Student List → tinjau → Confirm. Kuota dan duplikat diperiksa ulang; jika tidak cukup, seluruh pilihan diblokir. Riwayat Confirmed tersimpan. Konfirmasi bukan pembayaran dan tidak otomatis assign jadwal. Import tetap langsung menambah peserta; formatnya masih provisional.</p></li><li><b>Bedakan Reschedule dengan Drop + Add</b><p>Drop/Cancel membatalkan jadwal lama. Add Schedule membuat jadwal baru; assignment perlu diperiksa atau dibuat kembali. Ini bukan jalan pintas Reschedule. Participants dan referensi Session tetap dipertahankan.</p></li></ol><p className="muted">Data tersimpan di localStorage pada browser, alamat, dan port yang sama. Reset Data menghapus perubahan lokal V3 dan mengembalikan seed; jangan gunakan reset hanya untuk memasang patch. Demo clock bukan waktu hari ini. Contoh Workshop 28 Sep 2026 pukul 13:00 memiliki cutoff 11:00; tepat 11:00 reschedule diblokir. Mengubahnya ke 5 Oct berbenturan dengan jadwal yang ada; 6 Oct adalah contoh tanpa konflik pada seed.</p></div><div className="modalfooter"><button className="primary" onClick={close}>Tutup Panduan</button></div></>}
{modal.kind==='order'&&<><div className="modalbody"><p>Demonstrates event availability for student ordering. No actual orders are created.</p>{db.events.map(e=><div className="orderrow" key={e.id}><div><b>{e.name}</b><small>{e.type}</small></div><Tag tone={e.type==='Internal Meeting'?'red':'green'}>{e.type==='Internal Meeting'?'Blocked':'Available'}</Tag></div>)}<div className="notice"><Icon icon={ShieldCheck}/><span>Internal Meeting is blocked for students, including admin-on-behalf orders. Backend enforcement would be required in production.</span></div></div><div className="modalfooter"><button onClick={close}>Close</button></div></>}
</Modal>}
</div>}
function Metric({title,value,icon}){return <div className="metric"><div><small>{title}</small><strong>{value}</strong></div><span className="metricicon"><Icon icon={icon}/></span></div>}
function ScheduleTable({db,event,readonly=false,attendanceOnly=false,go,onReschedule,onHistory,onAssign,onDrop,onAdd}){const [menu,setMenu]=useState(null);const active=event.schedules.filter(s=>s.status!=='Dropped'),dropped=event.schedules.filter(s=>s.status==='Dropped');const list=readonly?active:event.schedules;return <>{!active.length&&!readonly&&<Empty title="No active schedule" desc="Add a replacement occurrence. Event members and existing sessions are still registered.">{onAdd&&<button onClick={onAdd}><Icon icon={Plus}/> Add Replacement Schedule</button>}</Empty>}{list.length>0?<div className="tablewrap"><table><thead><tr><th>Date</th>{!readonly&&<th>Main Teacher</th>}<th>Room</th><th>Time</th><th>Status</th>{!readonly&&<th>Action</th>}</tr></thead><tbody>{list.map(s=><tr key={s.id} className={s.status==='Dropped'?'dropped':''}><td><b>{dateLabel(s.date)}</b><small>{s.id}</small></td>{!readonly&&<td>{s.teacher}</td>}<td>{s.room}</td><td className="nowrap">{s.start}–{s.end}</td><td><Tag tone={s.status==='Ongoing'?'amber':s.status==='Dropped'?'':'green'}>{s.status}</Tag>{s.rescheduleCount>0&&<small>Rescheduled · {s.rescheduleCount} change(s)</small>}</td>{!readonly&&<td><div className="rowactions"><button className="text" onClick={()=>go('/attendance/'+s.id)}>See Details</button>{!attendanceOnly&&<button className="iconbtn" aria-label={'Schedule actions '+s.id} onClick={ev=>{const r=ev.currentTarget.getBoundingClientRect();setMenu({s,top:Math.min(r.bottom,window.innerHeight-300),left:Math.max(12,r.right-270)})}}><MoreHorizontal size={18}/></button>}</div></td>}</tr>)}</tbody></table></div>:readonly?<p className="muted">No active schedule.</p>:null}{dropped.length>0&&!readonly&&<p className="muted footnote">Dropped occurrences are kept for history. They do not count toward the active-schedule limit.</p>}{menu&&<><div className="popover-shield" onClick={()=>setMenu(null)}/><div className="action-popover" style={{top:menu.top,left:menu.left}}><button onClick={()=>{go('/attendance/'+menu.s.id);setMenu(null)}}>View Attendance</button><button disabled={!!rescheduleEligibility(db,event,menu.s)} title={rescheduleEligibility(db,event,menu.s)} onClick={()=>{onReschedule(menu.s);setMenu(null)}}>Reschedule</button>{rescheduleEligibility(db,event,menu.s)&&<small>{rescheduleEligibility(db,event,menu.s)}</small>}<button onClick={()=>{onHistory(menu.s);setMenu(null)}}>View History</button><button disabled={menu.s.status!=='Upcoming'||event.type==='Internal Meeting'} onClick={()=>{onAssign(menu.s);setMenu(null)}}>Assign Students</button><button className="danger" disabled={menu.s.status!=='Upcoming'} onClick={()=>{onDrop(menu.s);setMenu(null)}}>Cancel Schedule</button></div></>}</>}
